CREATE EXTENSION IF NOT EXISTS btree_gist; ALTER TABLE buildpulse_ad_orders DROP CONSTRAINT IF EXISTS buildpulse_ad_orders_no_schedule_overlap; ALTER TABLE buildpulse_ad_orders ADD CONSTRAINT buildpulse_ad_orders_no_schedule_overlap EXCLUDE USING gist (product_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status IN ('scheduled','active') AND starts_at IS NOT NULL AND ends_at IS NOT NULL);